commits.content:
html,
body {
  height: 100%;
}

body {
  margin: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  font-family: system-ui, -apple-system, sans-serif;

  background: #0f0f0f;
  color: #f5f5f5;
}

main {
  max-width: 600px;

  padding: 32px;

  text-align: center;
}

h1 {
  margin-bottom: 16px;

  font-size: 42px;
}

p {
  font-size: 18px;
  opacity: 0.7;
}
